def get_conn():
    conn = sqlite3.connect(DB_PATH, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db():
    with get_conn() as con:
        con.executescript("""
        CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'Crochet',
            description TEXT NOT NULL DEFAULT '',
            price REAL NOT NULL DEFAULT 700,
            image_path TEXT DEFAULT '',
            stock INTEGER NOT NULL DEFAULT 20,
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_code TEXT UNIQUE NOT NULL,
            customer_name TEXT NOT NULL,
            email TEXT NOT NULL,
            phone TEXT NOT NULL,
            fulfillment TEXT NOT NULL,
            address TEXT DEFAULT '',
            pickup_note TEXT DEFAULT '',
            payment_method TEXT NOT NULL,
            payment_status TEXT NOT NULL DEFAULT 'Pending',
            order_status TEXT NOT NULL DEFAULT 'New',
            items_json TEXT NOT NULL,
            subtotal REAL NOT NULL,
            delivery_fee REAL NOT NULL DEFAULT 0,
            total REAL NOT NULL,
            estimated_days INTEGER NOT NULL DEFAULT 7,
            admin_message TEXT DEFAULT '',
            customer_note TEXT DEFAULT '',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS settings (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );
        """)
        count = con.execute("SELECT COUNT(*) FROM products").fetchone()[0]
        if count == 0:
            starter_products = [
                ("Rose Crochet Scrunchie Set", "Accessories", "Soft handmade scrunchies with a romantic rose detail.", 700, "", 25),
                ("Crochet Rose Hair Tie", "Accessories", "A floral handmade hair accessory, made slowly with care.", 450, "", 25),
                ("Mini Crochet Flower", "Gifts", "A small crochet flower for gifts, bags, or room decor.", 350, "", 30),
                ("Crochet Bouquet", "Gifts", "A custom mini bouquet. Final price depends on size and colours.", 1200, "", 10),
                ("Crochet Keychain", "Accessories", "A cute handmade keychain; colours can be requested.", 400, "", 20),
                ("Custom Crochet Design", "Custom Orders", "Tell us your preferred colour and design after ordering.", 700, "", 10),
            ]
            now = datetime.now().isoformat(timespec="seconds")
            for p in starter_products:
                con.execute("""INSERT INTO products
                    (name,category,description,price,image_path,stock,active,created_at)
                    VALUES (?,?,?,?,?,?,1,?)""", (*p, now))
        con.execute("INSERT OR IGNORE INTO settings(key,value) VALUES('delivery_fee','200')")
        con.execute("INSERT OR IGNORE INTO settings(key,value) VALUES('default_days','7')")
        con.execute("INSERT OR IGNORE INTO settings(key,value) VALUES('pickup_note','Pickup details will be shared after confirmation.')")


def query_df(sql, params=()):
    with get_conn() as con:
        return pd.read_sql_query(sql, con, params=params)


def setting(key, fallback=""):
    with get_conn() as con:
        row = con.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
    return row["value"] if row else fallback


def set_setting(key, value):
    with get_conn() as con:
        con.execute("""INSERT INTO settings(key,value) VALUES(?,?)
                       ON CONFLICT(key) DO UPDATE SET value=excluded.value""",
                    (key, str(value)))


def money(value):
    return f"PKR {float(value):,.0f}"


def image_bytes_for_product(row):
    path = str(row.get("image_path", "") or "")
    if path and Path(path).exists():
        return Path(path).read_bytes()
    return base64.b64decode(DEFAULT_PRODUCT_IMAGE_B64) if DEFAULT_PRODUCT_IMAGE_B64 else None


def seed_default_photo():
    # Keep the customer's supplied example photo embedded in this one-file app.
    if not DEFAULT_PRODUCT_IMAGE_B64:
        return ""
    path = UPLOAD_DIR / "customer_example_scrunchies.jpeg"
    if not path.exists():
        path.write_bytes(base64.b64decode(DEFAULT_PRODUCT_IMAGE_B64))
    return str(path)


def get_products(active_only=True):
    where = "WHERE active=1" if active_only else ""
    return query_df(f"SELECT * FROM products {where} ORDER BY id DESC")


def init_state():
    defaults = {
        "cart": {}, "page": "Shop", "admin_logged_in": False,
        "customer_order_code": "", "search": "", "category_filter": "All",
    }
    for k, v in defaults.items():
        if k not in st.session_state:
            st.session_state[k] = v


init_db()
init_state()
example_image = seed_default_photo()

# Set the sample photo on the first sample product, without overwriting later admin choices.
with get_conn() as con:
    row = con.execute("SELECT image_path FROM products WHERE name='Rose Crochet Scrunchie Set' LIMIT 1").fetchone()
    if row and not row["image_path"] and example_image:
        con.execute("UPDATE products SET image_path=? WHERE name='Rose Crochet Scrunchie Set'", (example_image,))


def product_image(row, width="stretch"):
    data = image_bytes_for_product(row)
    if data:
        st.image(data, use_container_width=True)
    else:
        st.markdown("<div style='height:180px;border-radius:14px;background:#f8e8ee;display:flex;align-items:center;justify-content:center;font-size:4rem'>🧶🌹</div>", unsafe_allow_html=True)


def get_cart_rows():
    products = get_products(active_only=False).set_index("id", drop=False)
    rows = []
    for product_id, qty in st.session_state.cart.items():
        if product_id in products.index:
            p = products.loc[product_id].to_dict()
            if int(p["active"]) == 1:
                p["quantity"] = int(qty)
                p["line_total"] = float(p["price"]) * int(qty)
                rows.append(p)
    return rows


def cart_subtotal():
    return sum(r["line_total"] for r in get_cart_rows())


def add_to_cart(product_id):
    st.session_state.cart[product_id] = st.session_state.cart.get(product_id, 0) + 1


def admin_login():
    st.subheader("Admin sign in")
    st.caption("Manage products, orders, fulfilment timelines, and store performance.")
    with st.form("admin_login_form"):
        password = st.text_input("Admin password", type="password")
        submitted = st.form_submit_button("Sign in", type="primary", use_container_width=True)
    if submitted:
        if hmac.compare_digest(password, ADMIN_PASSWORD):
            st.session_state.admin_logged_in = True
            st.success("Signed in successfully.")
            st.rerun()
        else:
            st.error("Incorrect password. Please try again.")


def order_status_badge(status):
    return f"**{status}**"


def render_header():
    st.markdown("""
    <div class="hero">
      <div class="eyebrow">Small details. Big love.</div>
      <h1>Croshia Studio 🧶</h1>
      <p>Thoughtfully handmade crochet designs, created one stitch at a time.
      Find a little piece of handmade happiness or request something personal.</p>
      <span class="pill">Handmade to order</span><span class="pill">Made with care</span><span class="pill">Pakistan</span>
    </div>
    """, unsafe_allow_html=True)
    st.write("")


def render_shop():
    render_header()
    products = get_products()
    if products.empty:
        st.info("No products are listed yet. Please check back soon.")
        return

    left, right = st.columns([2, 1])
    with left:
        search = st.text_input("🔎 Search handmade designs", key="search", placeholder="Search scrunchies, flowers, keychains...")
    with right:
        cats = ["All"] + sorted(products["category"].dropna().unique().tolist())
        selected_category = st.selectbox("Category", cats, key="category_filter")

    if search.strip():
        products = products[products["name"].str.contains(search.strip(), case=False, na=False) |
                            products["description"].str.contains(search.strip(), case=False, na=False)]
    if selected_category != "All":
        products = products[products["category"] == selected_category]

    if products.empty:
        st.warning("No designs match your search.")
        return

    st.subheader("Made by hand, chosen by you")
    st.caption("The first design uses your supplied photo. Add your second design photo in Admin → Products.")
    cols = st.columns(3, gap="large")
    for i, (_, product) in enumerate(products.iterrows()):
        with cols[i % 3]:
            with st.container(border=True):
                product_image(product)
                st.markdown(f"### {product['name']}")
                st.caption(f"{product['category']} · {int(product['stock'])} available")
                st.write(product["description"])
                st.markdown(f"**{money(product['price'])}**")
                if int(product["stock"]) <= 0:
                    st.button("Out of stock", disabled=True, key=f"oos_{product['id']}", use_container_width=True)
                elif st.button("＋ Add to cart", key=f"add_{product['id']}", type="primary", use_container_width=True):
                    if st.session_state.cart.get(int(product["id"]), 0) < int(product["stock"]):
                        add_to_cart(int(product["id"]))
                        st.toast(f"{product['name']} added to your cart")
                    else:
                        st.warning("You've added all currently available stock.")
    st.write("")
    with st.expander("✨ Need a custom design?"):
        st.write("Choose **Custom Crochet Design** or leave a note during checkout describing the colour, size, or inspiration you have in mind. The admin will confirm the price and estimated completion time.")


def render_cart():
    st.title("Your shopping bag")
    rows = get_cart_rows()
    if not rows:
        st.info("Your cart is empty. Visit the Shop to discover handmade designs.")
        if st.button("Explore designs", type="primary"):
            st.session_state.page = "Shop"
            st.rerun()
        return
    for row in rows:
        c1, c2, c3, c4 = st.columns([3, 1, 1, 1])
        with c1:
            st.write(f"**{row['name']}**")
            st.caption(money(row["price"]) + " each")
        with c2:
            new_qty = st.number_input("Qty", min_value=1, max_value=max(1, int(row["stock"])), value=min(int(row["quantity"]), max(1, int(row["stock"]))), key=f"qty_{row['id']}")
        with c3:
            st.write(money(row["line_total"]))
        with c4:
            if st.button("Remove", key=f"remove_{row['id']}"):
                st.session_state.cart.pop(int(row["id"]), None)
                st.rerun()
        if int(new_qty) != int(row["quantity"]):
            st.session_state.cart[int(row["id"])] = int(new_qty)
            st.rerun()

    subtotal = cart_subtotal()
    st.divider()
    st.markdown(f"### Subtotal: {money(subtotal)}")
    st.caption("Delivery charges are added at checkout if you choose delivery.")
    if st.button("Continue to checkout", type="primary", use_container_width=True):
        st.session_state.page = "Checkout"
        st.rerun()


def render_checkout():
    st.title("Checkout")
    rows = get_cart_rows()
    if not rows:
        st.warning("Your cart is empty.")
        return
    subtotal = cart_subtotal()
    delivery_fee = float(setting("delivery_fee", "200"))
    default_days = int(setting("default_days", "7"))
    st.subheader("Order summary")
    for row in rows:
        st.write(f"• {row['name']} × {row['quantity']} — **{money(row['line_total'])}**")
    st.write(f"Subtotal: **{money(subtotal)}**")
    st.caption("Handmade items take time to create. The admin will confirm your expected completion date.")
    with st.form("checkout_form"):
        st.subheader("Your details")
        name = st.text_input("Full name *")
        email = st.text_input("Email address *")
        phone = st.text_input("Phone number *", placeholder="+92 3XX XXXXXXX")
        fulfillment = st.radio("How would you like to receive your order?", ["Delivery", "Pickup"], horizontal=True)
        address = ""
        pickup_note = ""
        actual_delivery_fee = 0.0
        if fulfillment == "Delivery":
            address = st.text_area("Complete delivery address *", placeholder="House/flat, street, area, city")
            actual_delivery_fee = delivery_fee
            st.caption(f"Delivery fee: {money(delivery_fee)}")
        else:
            pickup_note = st.text_input("Pickup name / preferred pickup detail *", placeholder="Name for pickup or preferred arrangement")
            st.caption("Pickup arrangements will be confirmed by the admin.")
        payment_method = st.selectbox("Payment method *", [
            "Cash on delivery / pay at pickup",
            "Bank transfer (admin will share details)",
            "Online payment gateway (not connected yet)"
        ])
        customer_note = st.text_area("Special instructions (optional)", placeholder="Colour requests, gift note, or design details...")
        st.info(f"Estimated making time is usually {default_days} days, but the admin will confirm the timeline after reviewing your order.")
        accepted = st.checkbox("I understand this is handmade and the completion time will be confirmed by the admin.")
        submitted = st.form_submit_button("Place order", type="primary", use_container_width=True)

    if submitted:
        errors = []
        if not name.strip(): errors.append("Enter your name.")
        if not email.strip() or "@" not in email or "." not in email.split("@")[-1]: errors.append("Enter a valid email address.")
        if not phone.strip() or len("".join(ch for ch in phone if ch.isdigit())) < 7: errors.append("Enter a valid phone number.")
        if fulfillment == "Delivery" and not address.strip(): errors.append("Enter your complete delivery address.")
        if fulfillment == "Pickup" and not pickup_note.strip(): errors.append("Enter a pickup name or detail.")
        if not accepted: errors.append("Please confirm the handmade-order timing note.")
        # Never accept a gateway option as if a real online payment was processed.
        if errors:
            for error in errors: st.error(error)
        else:
            current_rows = get_cart_rows()
            if not current_rows:
                st.error("Your cart is empty.")
                return
            for item in current_rows:
                with get_conn() as con:
                    stock = con.execute("SELECT stock,active FROM products WHERE id=?", (int(item["id"]),)).fetchone()
                if not stock or not stock["active"] or stock["stock"] < item["quantity"]:
                    st.error(f"Sorry, availability changed for {item['name']}. Please update your cart.")
                    return
            code = "CR-" + datetime.now().strftime("%y%m%d") + "-" + secrets.token_hex(3).upper()
            items_json = json.dumps([{
                "product_id": int(r["id"]), "name": r["name"], "quantity": int(r["quantity"]),
                "unit_price": float(r["price"]), "line_total": float(r["line_total"])
            } for r in current_rows])
            total = subtotal + actual_delivery_fee
            payment_status = "Not connected" if payment_method.startswith("Online payment") else "Pending"
            now = datetime.now().isoformat(timespec="seconds")
            with get_conn() as con:
                con.execute("""INSERT INTO orders
                    (order_code,customer_name,email,phone,fulfillment,address,pickup_note,payment_method,
                     payment_status,order_status,items_json,subtotal,delivery_fee,total,estimated_days,
                     admin_message,customer_note,created_at,updated_at)
                    VALUES (?,?,?,?,?,?,?,?,?,'New',?,?,?,?,?,'',?,?,?)""",
                    (code,name.strip(),email.strip(),phone.strip(),fulfillment,address.strip(),pickup_note.strip(),
                     payment_method,payment_status,items_json,subtotal,actual_delivery_fee,total,default_days,
                     customer_note.strip(),now,now))
                for item in current_rows:
                    con.execute("UPDATE products SET stock=MAX(0,stock-?) WHERE id=?", (int(item["quantity"]), int(item["id"])))
            st.session_state.cart = {}
            st.session_state.customer_order_code = code
            st.session_state.page = "Order Success"
            st.rerun()


def render_order_success():
    code = st.session_state.customer_order_code
    st.title("Thank you for supporting handmade 🧶")
    st.success("Your order has been placed!")
    st.write(f"Your order reference is **{code}**. Save it to track your order.")
    st.info("The shop admin will review your order and send an update about the estimated making and delivery/pickup time. Online gateway payments are not active in this demo; choose a manual payment method until a provider is connected.")
    if st.button("Track this order"):
        st.session_state.page = "Track Order"
        st.rerun()
    if st.button("Back to shop"):
        st.session_state.page = "Shop"
        st.rerun()


def render_track_order():
    st.title("Track your order")
    st.write("Enter your order reference and the email address used at checkout.")
    with st.form("track_form"):
        code = st.text_input("Order reference", value=st.session_state.customer_order_code)
        email = st.text_input("Checkout email")
        submitted = st.form_submit_button("Find my order", type="primary")
    if submitted:
        with get_conn() as con:
            order = con.execute("SELECT * FROM orders WHERE order_code=? AND lower(email)=lower(?)", (code.strip(), email.strip())).fetchone()
        if not order:
            st.error("We couldn't find an order matching those details.")
        else:
            st.markdown(f"### Order {order['order_code']}")
            st.write(f"**Status:** {order['order_status']}")
            st.write(f"**Payment:** {order['payment_status']} — {order['payment_method']}")
            st.write(f"**Fulfilment:** {order['fulfillment']}")
            st.write(f"**Total:** {money(order['total'])}")
            eta = order["estimated_days"]
            estimated_date = (datetime.fromisoformat(order["created_at"]) + timedelta(days=eta)).date()
            st.write(f"**Current estimated completion:** {estimated_date.strftime('%d %b %Y')} (estimate; admin may update it)")
            if order["admin_message"]:
                st.info("Message from the shop: " + order["admin_message"])
            try:
                items = json.loads(order["items_json"])
                for item in items:
                    st.write(f"• {item['name']} × {item['quantity']}")
            except Exception:
                pass


def render_admin_dashboard():
    st.title("Admin dashboard")
    st.caption("A private workspace for managing the handmade store.")
    if not st.session_state.admin_logged_in:
        admin_login()
        return
    if st.button("Sign out"):
        st.session_state.admin_logged_in = False
        st.rerun()

    tabs = st.tabs(["Overview", "Orders", "Products", "Store settings"])
    orders = query_df("SELECT * FROM orders ORDER BY created_at DESC")
    products_all = get_products(active_only=False)

    with tabs[0]:
        total_orders = len(orders)
        completed = int((orders["order_status"] == "Completed").sum()) if total_orders else 0
        active_orders = int((~orders["order_status"].isin(["Completed", "Cancelled"])).sum()) if total_orders else 0
        # Revenue is based on completed orders only; pending/in-progress orders are not counted as earned revenue.
        completed_orders = orders[orders["order_status"] == "Completed"] if total_orders else orders
        revenue = float(completed_orders["total"].sum()) if total_orders else 0
        cost_per_item = 0.0
        cols = st.columns(4)
        metrics = [("Total orders", total_orders), ("Active orders", active_orders), ("Completed orders", completed), ("Completed sales", money(revenue))]
        for col, (label, val) in zip(cols, metrics):
            with col:
                st.markdown('<div class="metric-card">', unsafe_allow_html=True)
                st.metric(label, val)
                st.markdown('</div>', unsafe_allow_html=True)
        st.caption("Completed sales are counted as revenue only after an order is marked Completed. Profit is an estimate and needs material/labour costs.")
        st.subheader("Most requested designs")
        demand = {}
        for _, order in orders.iterrows():
            try:
                for item in json.loads(order["items_json"]):
                    demand[item["name"]] = demand.get(item["name"], 0) + int(item["quantity"])
            except Exception:
                pass
        if demand:
            demand_df = pd.DataFrame([{"Design": k, "Units ordered": v} for k, v in sorted(demand.items(), key=lambda x: x[1], reverse=True)])
            st.bar_chart(demand_df.set_index("Design"))
            st.dataframe(demand_df, use_container_width=True, hide_index=True)
        else:
            st.info("Design demand will appear here after customers place orders.")
        if total_orders:
            st.subheader("Order status breakdown")
            status_df = orders["order_status"].value_counts().rename_axis("Status").reset_index(name="Orders")
            st.bar_chart(status_df.set_index("Status"))
        st.subheader("Low stock")
        low_stock = products_all[products_all["stock"] <= 5]
        if low_stock.empty:
            st.caption("No products have stock at or below 5.")
        else:
            st.dataframe(low_stock[["name", "stock", "active"]], use_container_width=True, hide_index=True)

    with tabs[1]:
        st.subheader("Orders")
        if orders.empty:
            st.info("No orders yet.")
        else:
            statuses = ["All", "New", "Confirmed", "In Progress", "Ready for Pickup", "Out for Delivery", "Completed", "Cancelled"]
            selected_status = st.selectbox("Filter by status", statuses)
            shown = orders if selected_status == "All" else orders[orders["order_status"] == selected_status]
            st.dataframe(shown[["order_code","customer_name","phone","fulfillment","total","payment_status","order_status","created_at"]], use_container_width=True, hide_index=True)
            codes = orders["order_code"].tolist()
            selected_code = st.selectbox("Select an order to manage", codes)
            order = orders[orders["order_code"] == selected_code].iloc[0]
            st.markdown(f"### {order['order_code']} · {order['customer_name']}")
            st.write(f"**Email:** {order['email']} · **Phone:** {order['phone']}")
            st.write(f"**Fulfilment:** {order['fulfillment']}")
            if order["fulfillment"] == "Delivery":
                st.write(f"**Address:** {order['address']}")
            else:
                st.write(f"**Pickup detail:** {order['pickup_note']}")
            st.write(f"**Payment method:** {order['payment_method']} · **Payment status:** {order['payment_status']}")
            st.write(f"**Customer note:** {order['customer_note'] or 'None'}")
            try:
                for item in json.loads(order["items_json"]):
                    st.write(f"• {item['name']} × {item['quantity']} — {money(item['line_total'])}")
            except Exception:
                pass
            with st.form("update_order_form"):
                new_status = st.selectbox("Order status", ["New", "Confirmed", "In Progress", "Ready for Pickup", "Out for Delivery", "Completed", "Cancelled"], index=["New", "Confirmed", "In Progress", "Ready for Pickup", "Out for Delivery", "Completed", "Cancelled"].index(order["order_status"]) if order["order_status"] in ["New", "Confirmed", "In Progress", "Ready for Pickup", "Out for Delivery", "Completed", "Cancelled"] else 0)
                new_payment = st.selectbox("Payment status", ["Pending", "Paid", "Partially paid", "Refunded", "Not connected"], index=["Pending", "Paid", "Partially paid", "Refunded", "Not connected"].index(order["payment_status"]) if order["payment_status"] in ["Pending", "Paid", "Partially paid", "Refunded", "Not connected"] else 0)
                days = st.number_input("Estimated making / preparation time (days)", min_value=1, max_value=120, value=int(order["estimated_days"]))
                admin_message = st.text_area("Message to customer (shown in order tracking)", value=order["admin_message"] or "", placeholder="Example: Your handmade order will be ready in 10–12 days. We will message you when it is ready.")
                save = st.form_submit_button("Save order update", type="primary")
            if save:
                now = datetime.now().isoformat(timespec="seconds")
                with get_conn() as con:
                    con.execute("""UPDATE orders SET order_status=?,payment_status=?,estimated_days=?,admin_message=?,updated_at=? WHERE order_code=?""",
                                (new_status,new_payment,int(days),admin_message.strip(),now,selected_code))
                st.success("Order updated. The customer can see your message on the tracking page.")
                st.rerun()
            csv = shown.to_csv(index=False).encode("utf-8")
            st.download_button("Download filtered orders CSV", csv, "croshia_orders.csv", "text/csv")

    with tabs[2]:
        st.subheader("Product catalogue")
        st.dataframe(products_all[["id","name","category","price","stock","active"]], use_container_width=True, hide_index=True)
        st.markdown("#### Add a new design")
        with st.form("add_product_form", clear_on_submit=True):
            name = st.text_input("Design name *")
            category = st.selectbox("Category", ["Accessories", "Gifts", "Home Decor", "Clothing", "Custom Orders", "Other"])
            description = st.text_area("Description")
            price = st.number_input("Price (PKR)", min_value=0, value=700, step=50)
            stock = st.number_input("Available quantity", min_value=0, value=10, step=1)
            uploaded = st.file_uploader("Design photo (JPG, PNG, WEBP)", type=["jpg","jpeg","png","webp"], key="new_product_photo")
            add_product = st.form_submit_button("Add design", type="primary")
        if add_product:
            if not name.strip():
                st.error("Please enter a design name.")
            else:
                image_path = ""
                if uploaded:
                    suffix = Path(uploaded.name).suffix.lower()
                    safe_name = f"product_{secrets.token_hex(6)}{suffix}"
                    image_path = str(UPLOAD_DIR / safe_name)
                    Path(image_path).write_bytes(uploaded.getvalue())
                with get_conn() as con:
                    con.execute("""INSERT INTO products(name,category,description,price,image_path,stock,active,created_at)
                                   VALUES(?,?,?,?,?,?,1,?)""",
                                (name.strip(),category,description.strip(),float(price),image_path,int(stock),datetime.now().isoformat(timespec="seconds")))
                st.success("Design added.")
                st.rerun()
        st.markdown("#### Edit or hide a design")
        if not products_all.empty:
            product_ids = products_all["id"].tolist()
            pid = st.selectbox("Choose product", product_ids, format_func=lambda x: f"{x} — {products_all[products_all['id']==x].iloc[0]['name']}")
            product = products_all[products_all["id"] == pid].iloc[0]
            with st.form("edit_product_form"):
                edit_name = st.text_input("Name", value=product["name"])
                edit_category = st.text_input("Category", value=product["category"])
                edit_desc = st.text_area("Description", value=product["description"])
                edit_price = st.number_input("Price (PKR)", min_value=0, value=int(product["price"]), step=50)
                edit_stock = st.number_input("Stock", min_value=0, value=int(product["stock"]), step=1)
                edit_active = st.checkbox("Visible in shop", value=bool(product["active"]))
                edit_photo = st.file_uploader("Replace photo (optional)", type=["jpg","jpeg","png","webp"], key="edit_product_photo")
                save_product = st.form_submit_button("Save product changes", type="primary")
            if save_product:
                image_path = product["image_path"] or ""
                if edit_photo:
                    suffix = Path(edit_photo.name).suffix.lower()
                    image_path = str(UPLOAD_DIR / f"product_{secrets.token_hex(6)}{suffix}")
                    Path(image_path).write_bytes(edit_photo.getvalue())
                with get_conn() as con:
                    con.execute("""UPDATE products SET name=?,category=?,description=?,price=?,stock=?,active=?,image_path=? WHERE id=?""",
                                (edit_name.strip(),edit_category.strip(),edit_desc.strip(),float(edit_price),int(edit_stock),int(edit_active),image_path,int(pid)))
                st.success("Product updated.")
                st.rerun()

    with tabs[3]:
        st.subheader("Store settings")
        with st.form("store_settings_form"):
            delivery = st.number_input("Delivery fee (PKR)", min_value=0, value=int(float(setting("delivery_fee", "200"))), step=50)
            days = st.number_input("Default estimated making time (days)", min_value=1, max_value=120, value=int(setting("default_days", "7")))
            pickup = st.text_area("Pickup information shown in settings", value=setting("pickup_note", "Pickup details will be shared after confirmation."))
            save_settings = st.form_submit_button("Save settings", type="primary")
        if save_settings:
            set_setting("delivery_fee", delivery)
            set_setting("default_days", days)
            set_setting("pickup_note", pickup)
            st.success("Store settings saved.")
        st.warning("Security: the starter admin password is naba123 as requested. Before putting this online, set the CROSHIA_ADMIN_PASSWORD environment variable to a strong, unique password. Do not reuse a personal password.")
        st.info("Payment gateway note: this app supports cash on delivery/pickup and bank transfer instructions. A real online gateway requires a merchant account, provider credentials, and server-side payment verification. The online gateway option is clearly marked as not connected and does not charge customers.")


def main():
    with st.sidebar:
        st.markdown("## 🧶 Croshia Studio")
        st.caption("Handmade crochet shop")
        page = st.radio("Navigate", ["Shop", "Cart", "Checkout", "Track Order", "Admin", "Order Success"], label_visibility="collapsed",
                        index=["Shop", "Cart", "Checkout", "Track Order", "Admin", "Order Success"].index(st.session_state.page) if st.session_state.page in ["Shop", "Cart", "Checkout", "Track Order", "Admin", "Order Success"] else 0)
        st.session_state.page = page
        st.divider()
        cart_count = sum(st.session_state.cart.values())
        st.metric("Items in cart", cart_count)
        st.caption("Made with care, stitch by stitch 💗")
    if st.session_state.page == "Shop":
        render_shop()
    elif st.session_state.page == "Cart":
        render_cart()
    elif st.session_state.page == "Checkout":
        render_checkout()
    elif st.session_state.page == "Track Order":
        render_track_order()
    elif st.session_state.page == "Admin":
        render_admin_dashboard()
    elif st.session_state.page == "Order Success":
        render_order_success()
    st.divider()
    st.markdown("<div style='text-align:center;color:#927b84;padding:1rem'>Croshia Studio · Handmade with love 🧶 · Every stitch tells a story</div>", unsafe_allow_html=True)


if __name__ == "__main__":
    main()
